def cache_sim(capacity, ttl, ops):
    from collections import defaultdict

    # Track write time for each key (for expiration)
    write_time = {}
    # Track the order of most recent use
    lru_order = []
    # Store the actual values
    cache = {}

    results = []

    for op in ops:
        op_type = op[0]
        t = op[1]
        key = op[2]

        # Check if key has expired
        def is_expired(k):
            if k not in write_time:
                return True
            return write_time[k] + ttl <= t

        # Remove key from lru_order if present
        def remove_from_lru(k):
            if k in lru_order:
                lru_order.remove(k)

        if op_type == 'put':
            value = op[3]

            # If key is absent and cache is full, evict LRU
            if key not in write_time or is_expired(key):
                # Key is absent
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]
                    del write_time[lru_key]
            else:
                # Key exists and is not expired, remove from LRU order
                remove_from_lru(key)

            # Add the new entry
            cache[key] = value
            write_time[key] = t
            lru_order.append(key)

        elif op_type == 'get':
            if key in write_time and not is_expired(key):
                # Key exists and is not expired
                results.append(cache[key])
                # Make it most recently used
                remove_from_lru(key)
                lru_order.append(key)
            else:
                # Key absent or expired
                results.append(-1)

    return results

